CREATE TABLE tenants(id uuid PRIMARY KEY, name varchar(120) NOT NULL, contact varchar(250) NOT NULL DEFAULT '', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE sites(id uuid PRIMARY KEY,tenant_id uuid NOT NULL REFERENCES tenants(id),code varchar(32) NOT NULL,name varchar(120) NOT NULL,address varchar(250) NOT NULL DEFAULT '',status text NOT NULL CHECK(status IN ('PROVISIONING','ACTIVE','SUSPENDED')),warehouse_id uuid NOT NULL UNIQUE,register_id uuid NOT NULL UNIQUE,warehouse_ready boolean NOT NULL DEFAULT false,register_ready boolean NOT NULL DEFAULT false,version integer NOT NULL DEFAULT 1,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(tenant_id,code));
CREATE TABLE memberships(id uuid PRIMARY KEY,tenant_id uuid NOT NULL REFERENCES tenants(id),subject_id text NOT NULL,role text NOT NULL CHECK(role IN ('OWNER','MANAGER','CASHIER','STOCK','ACCOUNTANT')),status text NOT NULL CHECK(status IN ('ACTIVE','BLOCKED')),site_ids uuid[] NOT NULL DEFAULT '{}',version integer NOT NULL DEFAULT 1,UNIQUE(tenant_id,subject_id));
CREATE TABLE invitations(id uuid PRIMARY KEY,tenant_id uuid NOT NULL REFERENCES tenants(id),role text NOT NULL CHECK(role IN ('MANAGER','CASHIER','STOCK','ACCOUNTANT')),site_ids uuid[] NOT NULL,target_subject_id text NOT NULL,token_hash text NOT NULL UNIQUE,expires_at timestamptz NOT NULL,confirmed_by text NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),consumed_at timestamptz);
CREATE TABLE audit(id uuid PRIMARY KEY,tenant_id uuid NOT NULL REFERENCES tenants(id),actor text NOT NULL,action text NOT NULL,entity_id uuid NOT NULL,before_data jsonb,after_data jsonb,created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX audit_tenant_time ON audit(tenant_id,created_at DESC);
CREATE TABLE idempotency(scope text NOT NULL,key text NOT NULL,body_hash text NOT NULL,response jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(scope,key));
CREATE TABLE outbox(id uuid PRIMARY KEY,type text NOT NULL,payload jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),lease_until timestamptz,delivered_at timestamptz);
CREATE TABLE inbox(id uuid PRIMARY KEY,processed_at timestamptz NOT NULL DEFAULT now());
